public static MXTDataCorrectionLog logRecord(Common _record, Description255 _name)
{
    MXTDataCorrectionLog log;

    log.RefTableId = _record.TableId;
    log.RefRecId   = _record.RecId;
    log.Name       = _name;
    log.RecData    = [_record];

    if (new DictTable(_record.TableId).dataPrCompany())
    {
        log.RefDataAreaId = _record.DataAreaId;
    }

    log.insert();

    return log;
}

/// <summary>
/// Inserts the logged record again with its original RecId. Uses doInsert, so the insert method of the table doesn't run.
/// </summary>
public Common restoreRecord()
{
    Common record = conPeek(this.RecData, 1);

    changecompany(this.RefDataAreaId ? this.RefDataAreaId : curExt())
    {
        record.doInsert();
        MXTDataCorrectionLog::restoreRecId(record, this.RefRecId);
    }

    return record;
}

/// <summary>
/// Gives a record that was just inserted the RecId it had before, in the transaction of the caller, and reads it again.
/// </summary>
public static void restoreRecId(Common _record, RefRecId _oldRecId)
{
    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

    TableId   rootTableId = SysDictTable::getRootTable(_record.TableId);
    DictTable dictTable   = new DictTable(rootTableId);
    Common    existing    = dictTable.makeRecord();

    if (!_record.RecId || !_oldRecId)
    {
        throw error(strFmt("@MXT:DataCorrectionRecIdMissing", dictTable.name()));
    }

    select firstonly crosscompany RecId from existing
        where existing.RecId == _oldRecId;

    if (existing.RecId)
    {
        throw error(strFmt("@MXT:DataCorrectionRecIdExists", _oldRecId, dictTable.name()));
    }

    str sql = strFmt('UPDATE %1 SET RECID = @OLDRECID WHERE RECID = @NEWRECID AND PARTITION = @PARTITION',
        dictTable.name(DbBackend::Sql));
    Map parameters = SqlParams::create();

    parameters.add('OLDRECID', _oldRecId);
    parameters.add('NEWRECID', _record.RecId);
    parameters.add('PARTITION', getCurrentPartitionRecId());

    new SqlStatementExecutePermission(sql).assert();
    Connection connection = new Connection();
    int updated = connection.createStatement().executeUpdateWithParameters(sql, parameters);
    CodeAccessPermission::revertAssert();

    if (updated != 1)
    {
        throw error(strFmt("@MXT:DataCorrectionRecIdMissing", dictTable.name()));
    }

    // The kernel doesn't see the UPDATE. Without the flush, a transaction that deleted the record before
    // reads the new RecId from the record cache until it ends
    TableId cachedTableId = _record.TableId;

    while (cachedTableId)
    {
        DictTable cachedTable = new DictTable(cachedTableId);

        if (cachedTable.cacheLookup() != RecordCacheLevel::None)
        {
            Dictionary::dataFlush(cachedTableId);
        }

        cachedTableId = cachedTable.extends();
    }

    // Not into the inserted buffer: in that transaction it comes back empty.
    // Not through the cache: it would keep the new RecId there after the commit
    Common restored = new DictTable(_record.TableId).makeRecord();

    restored.disableCache(true);

    select firstonly crosscompany restored
        where restored.RecId == _oldRecId;

    _record.data(restored);
}

public static void deleteOlderThan(Days _days)
{
    MXTDataCorrectionLog log;
    utcdatetime          limit = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -max(_days, 0));

    delete_from log
        where log.CreatedDateTime < limit;
}

public display TableNameShort refTableName()
{
    return tableId2Name(this.RefTableId);
}
